import{_ as s,o as a,c as t,a2 as o}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"跟做：选用生产组件与注册演示场景","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/design-system","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/design-system.md","filePath":"tutorials/design-system.md"}'),i={name:"tutorials/design-system.md"};function d(n,e,r,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="跟做-选用生产组件与注册演示场景" tabindex="-1">跟做：选用生产组件与注册演示场景 <a class="header-anchor" href="#跟做-选用生产组件与注册演示场景" aria-label="Permalink to &quot;跟做：选用生产组件与注册演示场景&quot;">​</a></h1><p>设计系统展厅（<code>/design-system</code>）是给&quot;替换模板做自己的产品&quot;这一步用的参考间：所有已登录用户都能从左下角用户区打开设置，再选择「设计系统」，里面看到的颜色、字体、间距、组件和图标就是业务页面正在用的那一份——展厅不维护第二份颜色表或展示组件副本，所以这里看到什么，产品就是什么。本章走一遍四类展厅（基础 / 组件 / 场景 / 图标）、示例如何注册自己的演示场景、以及示例移除后展厅如何变化。</p><h2 id="_1-先体验-从设置到展厅" tabindex="-1">1. 先体验：从设置到展厅 <a class="header-anchor" href="#_1-先体验-从设置到展厅" aria-label="Permalink to &quot;1. 先体验：从设置到展厅&quot;">​</a></h2><p>运行 <code>just dev</code>，登录后点击左下角用户区域进入设置，再从设置目录选择「设计系统」。旧 <code>/design-system</code> 书签同样进入设置中的展厅，路径共用同一个懒加载块。页面分四个标签：<strong>基础</strong>列出颜色令牌、字体和间距圆角；<strong>组件</strong>可以实际操作按钮、表单控件、弹层和反馈组件；<strong>场景</strong>包含核心场景和示例注册的场景；<strong>图标</strong>是按需加载、可按名称查找的目录。切到 English 和暗色再看一遍，各语言与主题组合共用生产组件。</p><h2 id="_2-基础与组件-直接读生产-tokens" tabindex="-1">2. 基础与组件：直接读生产 tokens <a class="header-anchor" href="#_2-基础与组件-直接读生产-tokens" aria-label="Permalink to &quot;2. 基础与组件：直接读生产 tokens&quot;">​</a></h2><p>基础标签里的令牌值不是写死的色卡，而是渲染时用 <code>getComputedStyle</code> 从当前文档实时读取的计算值：切到暗色主题后重新进入页面，列表里的值就是暗色令牌的当前值。点击「复制」拿到的是此刻的取值——模板换肤时这里自动跟随。字体与间距圆角直接用生产工具类渲染（<code>text-sm</code>、<code>p-4</code>、<code>rounded-lg</code>…）。</p><p>组件标签操作的是 <code>@saas/ui</code> 的真实组件：按钮的六种变体、加载（<code>aria-busy</code> + 旋转图标）、禁用状态；输入框、文本域、下拉、开关；「模拟校验错误」会同时给出 <code>aria-invalid</code> 标记、错误文案和 destructive 告警——错误状态不靠颜色单独传达。弹层演示用的是与业务删除确认相同的 AlertDialog：打开后焦点移入对话框，Esc 或「取消」关闭，「确认删除」只在局部状态里打一条演示提示，不发起任何请求。</p><h2 id="_3-场景-隔离-fixtures-与示例注册" tabindex="-1">3. 场景：隔离 fixtures 与示例注册 <a class="header-anchor" href="#_3-场景-隔离-fixtures-与示例注册" aria-label="Permalink to &quot;3. 场景：隔离 fixtures 与示例注册&quot;">​</a></h2><p>场景标签里的通用表单、列表、空态使用隔离的 fixtures 和组件局部状态：保存不发起请求，选择只影响本页，空态用「填充 / 清空」在两种状态间切换——它们演示的是形态，不是某个业务功能。</p><p>示例可以通过组装点注册自己的场景（<code>ExampleContribution.scenes</code>，声明 <code>id</code>、双语文案 key 与可选的交互渲染体）：便签示例（默认不注册；经 <code>scripts/example-add.mjs</code> 装回后）注册了一个「便签示例」场景，场景标题用示例自己的命名空间解析（<code>notes.nav.notes</code>），卡片上标注来源示例。删例工具移除示例后，这些场景随示例一起消失——Core-only 组合里场景标签只剩通用场景，并显示一条&quot;当前组合没有示例场景&quot;的说明，基础展厅保持完整。知识库的保存冲突场景（UI07）、附件图标和上传状态场景（UI08）与导出状态和通知显示场景（UI09）都由这条注册通道交付，渲染体用生产组件演示保存反馈、附件上传生命周期，以及状态徽标到通知标题的显示映射，只用演示数据。</p><h2 id="_4-图标-按需加载的目录" tabindex="-1">4. 图标：按需加载的目录 <a class="header-anchor" href="#_4-图标-按需加载的目录" aria-label="Permalink to &quot;4. 图标：按需加载的目录&quot;">​</a></h2><p>图标标签分三部分。上半部分是 <strong>ModuleIcon 矩阵</strong>：10 组分类色 × 裸色/平色/柔和/高光四种外观，在亮、暗两张 scoped 预览表里各渲染一遍——分类色只做小面积模块标识（侧栏、模块入口），取色独立于语义状态色；Core 模块的颜色登记在 <code>packages/views/src/shell/module-registry.ts</code>，示例模块通过 <code>ExampleContribution.moduleIcons</code> 声明自己路由的颜色并随示例一起移除。中间是<strong>文件图标样例</strong>：附件与文件列表按「文件名 → 后缀（最长匹配）→ MIME」解析为 Material Icon Theme 5.38.1 的 vendored 子集（32 枚，MIT 许可，署名见仓库根 <code>THIRD-PARTY-NOTICES.md</code>）；导出行只展示版本、状态与过期时间、不含文件名，因此暂不使用文件图标。下半部分才是精选的 Lucide 图标目录，按「操作 / 导航 / 状态 / 对象」四类组织，类别色来自生产令牌（<code>text-primary</code>、<code>text-link</code>、<code>text-success</code>、<code>text-warning</code>）。整个图标标签在自己的异步分块里，只有第一次打开才会下载——首包永远不包含它，性能预算（<code>scripts/perf/baselines.json</code>）不因此调整。每个图标按钮的可访问名称是本地化的「复制图标名称 X」，点击复制图标名，复制结果用文字反馈而不是颜色。Lucide 图标来自 <a href="https://lucide.dev" target="_blank" rel="noreferrer">lucide.dev</a>，ISC 许可，可以替换为任何兼容许可的图标库；想扩充目录就在 <code>icon-catalog.tsx</code> 的分类表里加一行。</p><h2 id="_5-可访问交互" tabindex="-1">5. 可访问交互 <a class="header-anchor" href="#_5-可访问交互" aria-label="Permalink to &quot;5. 可访问交互&quot;">​</a></h2><p>展厅没有为演示降低无障碍标准：标签页是真实的 <code>tablist/tab</code>，弹层焦点由对话框原语管理，图标按钮有本地化名称，复制反馈走 <code>role=&quot;status&quot;</code> 文字区域，焦点环统一使用 <code>ring</code> token。搜索框、单选、开关都是原生控件或带完整 ARIA 状态的组件，键盘可完整操作。演示数据与当前用户的业务数据完全隔离：场景不查询、不写入任何真实资源，这也是展厅可以向所有已登录用户开放的原因。</p><h2 id="_6-验证" tabindex="-1">6. 验证 <a class="header-anchor" href="#_6-验证" aria-label="Permalink to &quot;6. 验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/design-system.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/app-shell.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>design-system 测试在真实 Router 里走设置目录入口可见性、令牌搜索与复制反馈、组件状态操作、弹层焦点、场景隔离、图标查找与复制，以及四种「语言 × 主题」组合；app-shell 测试保证设置目录中的展厅入口在登录后出现、未登录隐藏。场景断言写成组合无关——删例组合跑同一份文件会验证&quot;示例场景消失、基础展厅保留&quot;。<code>just check</code> 里的 bundle 预算计量确认展厅与图标目录只在异步分块中——<code>scripts/perf/baselines.json</code> 的 <code>lazyPatterns</code> 把这条懒加载边界固化为门槛，展厅分块若回流首包会直接失败。注册新示例时，在 <code>ExampleContribution</code> 里声明 <code>scenes</code> 即可加入场景标签，无需改动展厅代码。</p><hr><p>源码版本：<code>e2df5399c4b9</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/tutorials/29-design-system.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,19)])])}const k=s(i,[["render",d]]);export{u as __pageData,k as default};
